/**
 * THE PARITY PROOF for members-only branches and pull requests (`docs/security/private-repos.md`
 * §19): every `oid_blind__`, `sealed_ref__` and `sealed_patch__` vector in
 * `forge-contracts/vectors/` (generated by `tools/private-repos-vectors/members_git.py`), run
 * against the web's blinds (`./blind`), its members-only ref updates (`./members-ref`), the
 * members-only PR / head-update path of its collab seal transform (`lib/repo/private-writes.ts`
 * `sealContent`) and its members ref union (`lib/repo/members-refs.ts`). forge-core
 * `members_git::conformance` runs the same files, with the same input and output shapes. Each
 * case has an allow-list of input keys at every depth. The helper-only `members_pack_plan` and
 * `publish_guard` cases are not run here (the git remote helper is Rust only).
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

import { base58Decode, base58Encode } from '../auth/base58'
import { gitPlaneDocWellFormed, toRefUpdate } from '../repo/contract'
import { membersUpdatesOf } from '../repo/members-refs'
import { sealContent } from '../repo/private-writes'
import { RoleOracle, countApprovals, type Review } from '../rules/v2'
import { compareKey, type RefUpdate } from '../rules'
import { bytesToBase64, type PlainDocument } from '../sdk'
import { BlindMap, blind, check, headOf, isNull, type Alert } from './blind'
import { bytesToHex, hexToBytes } from './bytes'
import { TooLargeError, V3, docAd, openContent, type OpenContext, type OpenResult, type PrivateDoc, type StoredPrivateDoc } from './doc'
import { IdSet, privateId } from './ids'
import { EpochKeys } from './keys'
import { openMembersRef, type RefOpened, type RefUpdateType } from './members-ref'
import { sealMembersDocWithNonce, sealMembersRefWithNonce } from './testing'
import { MalformedError, encodeTlv, type DocFields, type PrivateDocType } from './tlv'

type Json = null | boolean | number | string | Json[] | { [k: string]: Json }
type Obj = { readonly [k: string]: Json }

interface Vector {
  readonly name: string
  readonly description: string
  readonly case: string
  readonly rules: string
  readonly input: Obj
  readonly expected: Json
}

const VECTORS_DIR = resolve(process.cwd(), '..', 'forge-contracts', 'vectors')
/** The cases this harness runs (forge-core `members_git::conformance::CASES` minus the helper-only two). */
const CASES = ['oid_blind', 'sealed_ref', 'sealed_patch']
const FILES = readdirSync(VECTORS_DIR)
  .filter((f) => CASES.some((c) => f.startsWith(`${c}__`)) && f.endsWith('.json'))
  .sort()

// ---------------------------------------------------------------------------------------------
// Input allow-lists
// ---------------------------------------------------------------------------------------------

type Shape =
  | { readonly kind: 'leaf' }
  | { readonly kind: 'each'; readonly of: Shape }
  | { readonly kind: 'values'; readonly of: Shape }
  | { readonly kind: 'object'; readonly fields: { readonly [k: string]: Shape } }

const LEAF: Shape = { kind: 'leaf' }
const each = (of: Shape): Shape => ({ kind: 'each', of })
const values = (of: Shape): Shape => ({ kind: 'values', of })
const object = (fields: { readonly [k: string]: Shape }): Shape => ({ kind: 'object', fields })
const leafFields = (...keys: string[]) => Object.fromEntries(keys.map((k) => [k, LEAF]))
const leaves = (...keys: string[]): Shape => object(leafFields(...keys))

const DOC_KEYS = [
  'type', 'vis', 'ownerId', 'epoch', 'number', 'targetId', 'patchId', 'refNameHash', 'newOid', 'prevOid',
  'force', 'baseRefNameHash', 'sourceRefNameHash', 'id', 'createdAtBlockHeight', 'updatedAtBlockHeight', 'enc',
]
const OPEN_CONTEXT = object({ keys: values(LEAF), anchors: values(leaves('id', 'height', 'statedHeight')), members: LEAF, burned: LEAF })
/** The collaboration properties a `sealed_patch` seal may carry (the `private_collab_seal` set, `asMember`, `vis` and a head update's `oid`). */
const COLLAB_PROPS = [
  'number', 'title', 'body', 'baseRefName', 'baseRefNameHash', 'sourceRefName', 'sourceRefNameHash', 'sourceRepoId',
  'headOid', 'patchManifestHash', 'draft', 'targetId', 'path', 'replyTo', 'reviewId', 'commitOid', 'line', 'startLine',
  'side', 'patchId', 'verdict', 'commentCount', 'targetNumber', 'kind', 'value', 'refId', 'asMember', 'vis', 'oid',
]

const SHAPES: Readonly<Record<string, Shape>> = {
  oid_blind: object({
    ...leafFields('op', 'salt', 'oid', 'plain', 'real', 'author'),
    patch: leaves('headOid', 'real', 'salt'),
    headUpdates: each(leaves('id', 'createdAt', 'oid', 'real', 'salt')),
    reviews: each(leaves('id', 'reviewer', 'verdict', 'commitOid', 'createdAt')),
  }),
  sealed_ref: object({
    ...leafFields('op', 'repoId', 'key', 'epoch', 'type', 'ownerId', 'refName', 'newOid', 'prevOid', 'force', 'salt', 'nonce'),
    context: OPEN_CONTEXT,
    doc: leaves(...DOC_KEYS),
    rows: each(
      leaves('id', 'ownerId', 'createdAt', 'createdAtBlockHeight', 'protected', 'refNameHash', 'newOid', 'prevOid', 'enc', 'refName', 'vis', 'force', 'epoch'),
    ),
  }),
  sealed_patch: object({
    ...leafFields('op', 'repoId', 'key', 'epoch', 'type', 'ownerId', 'basePublic', 'sourcePublic', 'nonce', 'plainHead'),
    props: leaves(...COLLAB_PROPS),
    head: leaves('real', 'salt'),
    context: OPEN_CONTEXT,
    doc: leaves(...DOC_KEYS),
  }),
}

function isObj(v: Json | undefined): v is Obj {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

/** Refuse any key the shape does not list, at every depth. */
function checkShape(value: Json, shape: Shape, path: string): void {
  switch (shape.kind) {
    case 'leaf': {
      const scalar = (x: Json) => !isObj(x) && !Array.isArray(x)
      expect(Array.isArray(value) ? value.every(scalar) : scalar(value), `${path}: expected a scalar`).toBe(true)
      return
    }
    case 'each':
      expect(Array.isArray(value), `${path}: expected an array`).toBe(true)
      for (const [i, x] of (value as Json[]).entries()) checkShape(x, shape.of, `${path}[${i}]`)
      return
    case 'values':
      expect(isObj(value), `${path}: expected an object`).toBe(true)
      for (const [k, x] of Object.entries(value as Obj)) checkShape(x, shape.of, `${path}.${k}`)
      return
    case 'object': {
      expect(isObj(value), `${path}: expected an object`).toBe(true)
      const o = value as Obj
      expect(Object.keys(o).filter((k) => !(k in shape.fields)), `${path}: unknown keys`).toEqual([])
      for (const [k, x] of Object.entries(o)) checkShape(x, shape.fields[k] as Shape, `${path}.${k}`)
      return
    }
  }
}

// ---------------------------------------------------------------------------------------------
// Input conversion
// ---------------------------------------------------------------------------------------------

const str = (o: Obj, k: string): string => {
  const v = o[k]
  if (typeof v !== 'string') throw new TypeError(`${k}: expected a string`)
  return v
}
const num = (o: Obj, k: string): number => {
  const v = o[k]
  if (typeof v !== 'number') throw new TypeError(`${k}: expected a number`)
  return v
}
const obj = (o: Obj, k: string): Obj => {
  const v = o[k]
  if (!isObj(v)) throw new TypeError(`${k}: expected an object`)
  return v
}
const arr = (o: Obj, k: string): Obj[] => {
  const v = o[k]
  if (!Array.isArray(v) || !v.every(isObj)) throw new TypeError(`${k}: expected an array of objects`)
  return v as Obj[]
}
const hex = (o: Obj, k: string): Uint8Array => hexToBytes(str(o, k))
const optHex = (o: Obj, k: string): Uint8Array | undefined => (k in o ? hex(o, k) : undefined)

function storedDoc(d: Obj): StoredPrivateDoc {
  return {
    type: str(d, 'type') as PrivateDocType,
    vis: 'vis' in d ? (str(d, 'vis') as 'public' | 'private') : undefined,
    ownerId: privateId(str(d, 'ownerId')),
    epoch: num(d, 'epoch'),
    number: 'number' in d ? num(d, 'number') : undefined,
    targetId: optHex(d, 'targetId'),
    patchId: optHex(d, 'patchId'),
    refNameHash: optHex(d, 'refNameHash'),
    newOid: optHex(d, 'newOid'),
    prevOid: optHex(d, 'prevOid'),
    force: d['force'] === true,
    baseRefNameHash: optHex(d, 'baseRefNameHash'),
    sourceRefNameHash: optHex(d, 'sourceRefNameHash'),
    id: 'id' in d ? privateId(str(d, 'id')) : undefined,
    createdAtBlockHeight: 'createdAtBlockHeight' in d ? num(d, 'createdAtBlockHeight') : undefined,
    updatedAtBlockHeight: 'updatedAtBlockHeight' in d ? num(d, 'updatedAtBlockHeight') : undefined,
    enc: hex(d, 'enc'),
  }
}

/** A reader's context in the §11 vector shape (forge-core `open_context`). */
async function openContextOf(repoId: Uint8Array, c: Obj): Promise<OpenContext> {
  const ring = new Map<number, EpochKeys>()
  for (const [e, k] of Object.entries(obj(c, 'keys'))) ring.set(Number(e), await EpochKeys.import(repoId, Number(e), hexToBytes(String(k))))
  const members = c['members']
  const burned = c['burned']
  return {
    keys: ring,
    anchors: new Map(
      Object.entries(obj(c, 'anchors')).map(([e, v]) => {
        const a = v as Obj
        const statedHeight = num(a, a['statedHeight'] === undefined ? 'height' : 'statedHeight')
        return [Number(e), { id: privateId(str(a, 'id')), height: num(a, 'height'), statedHeight }]
      }),
    ),
    members: new IdSet(Array.isArray(members) ? members.map((m) => privateId(String(m))) : []),
    burned: new Set(Array.isArray(burned) ? burned.map(Number) : []),
  }
}

function fieldsJson(f: DocFields): Json {
  const out: { [k: string]: Json } = {}
  for (const [k, v] of Object.entries(f)) {
    if (v instanceof Uint8Array) out[k] = bytesToHex(v)
    else if (Array.isArray(v)) out[k] = [...v]
    else out[k] = v as Json
  }
  return out
}

function openJson(r: OpenResult): Json {
  if (r.status === 'readable') return { status: 'readable', fields: fieldsJson(r.fields) }
  return r.status === 'unreadable' ? { status: 'unreadable', reason: r.reason } : { status: 'malformed' }
}

const alertJson = (a: Alert): Json => ({ field: a.field, kind: a.kind })

function sealError(e: unknown): Json {
  if (e instanceof MalformedError) return { error: 'malformed' }
  if (e instanceof TooLargeError) return { error: 'tooLarge' }
  throw e
}

// ---------------------------------------------------------------------------------------------
// oid_blind
// ---------------------------------------------------------------------------------------------

async function runOidBlind(inp: Obj): Promise<Json> {
  const salt = optHex(inp, 'salt')
  switch (str(inp, 'op')) {
    case 'blind': {
      const b = await blind(salt as Uint8Array, hex(inp, 'oid'))
      if (b === null) throw new Error('not an OID width')
      return { blind: bytesToHex(b) }
    }
    case 'check':
      return { status: await check(hex(inp, 'plain'), optHex(inp, 'real'), salt) }
    case 'prFold': {
      // everyone folds the head and the approvals on the blinds as written (rule C); members
      // learn the real head of verified blinds only
      const map = new BlindMap()
      const alerts: Json[] = []
      const learn = async (at: string, o: Obj, plainKey: string) => {
        const a = await map.learn('headOid', hex(o, plainKey), optHex(o, 'real'), optHex(o, 'salt'))
        if (a !== null) alerts.push({ at, kind: a.kind })
      }
      const patch = obj(inp, 'patch')
      await learn('patch', patch, 'headOid')
      const updates = [...arr(inp, 'headUpdates')].sort((a, b) => compareKey({ createdAt: num(a, 'createdAt'), id: str(a, 'id') }, { createdAt: num(b, 'createdAt'), id: str(b, 'id') }))
      let head = str(patch, 'headOid')
      for (const u of updates) {
        await learn(str(u, 'id'), u, 'oid')
        head = str(u, 'oid')
      }
      const reviews: Review[] = arr(inp, 'reviews').map((r) => ({
        id: str(r, 'id'),
        reviewer: str(r, 'reviewer'),
        verdict: num(r, 'verdict'),
        commitOid: str(r, 'commitOid'),
        createdAt: num(r, 'createdAt'),
      }))
      const oracle = new RoleOracle(reviews.map((r) => ({ identity: r.reviewer, role: 'maintainer', createdAt: 0 })))
      const approvals = countApprovals(reviews, oracle, head, new Set(), str(inp, 'author'))
      const out: { [k: string]: Json } = { head, approvers: [...approvals.approvers], alerts }
      const real = map.realOf(head)
      if (real !== undefined) out['realHead'] = real
      return out
    }
    default:
      throw new Error(`oid_blind op ${str(inp, 'op')}`)
  }
}

// ---------------------------------------------------------------------------------------------
// sealed_ref
// ---------------------------------------------------------------------------------------------

function refOpenedJson(o: RefOpened): Json {
  switch (o.status) {
    case 'readable': {
      const ref: { [k: string]: Json } = { name: o.ref.name, newOid: bytesToHex(o.ref.newOid) }
      if (o.ref.prevOid !== undefined) ref['prevOid'] = bytesToHex(o.ref.prevOid)
      return { status: 'readable', ref, alerts: o.ref.alerts.map(alertJson) }
    }
    case 'unreadable':
      return { status: 'unreadable', reason: o.reason }
    case 'malformed':
      return { status: 'malformed' }
  }
}

/** A union row as the web reads it: base58 ids, base64 byte arrays (forge-core `row_doc`). */
function rowDoc(row: Obj): { doc: PlainDocument; isProtected: boolean } {
  const doc: PlainDocument = {}
  let isProtected = false
  for (const [k, v] of Object.entries(row)) {
    switch (k) {
      case 'id':
      case 'ownerId':
        doc[`$${k}`] = base58Encode(hexToBytes(String(v)))
        break
      case 'createdAt':
      case 'createdAtBlockHeight':
        doc[`$${k}`] = v
        break
      case 'protected':
        isProtected = v === true
        break
      case 'refNameHash':
      case 'newOid':
      case 'prevOid':
      case 'enc':
        doc[k] = bytesToBase64(hexToBytes(String(v)))
        break
      case 'refName':
      case 'vis':
      case 'force':
      case 'epoch':
        doc[k] = v
        break
      default:
        throw new Error(`unknown union row key ${k}`)
    }
  }
  return { doc, isProtected }
}

function updateJson(u: RefUpdate): Json {
  const out: { [k: string]: Json } = { id: bytesToHex(base58Decode(u.id)), newOid: u.newOid, force: u.force === true, protected: u.protected === true }
  if (u.prevOid !== undefined && u.prevOid !== '') out['prevOid'] = u.prevOid
  return out
}

async function runSealedRef(inp: Obj): Promise<Json> {
  const repoId = hex(inp, 'repoId')
  switch (str(inp, 'op')) {
    case 'seal': {
      const epoch = num(inp, 'epoch')
      const keys = await EpochKeys.import(repoId, epoch, hex(inp, 'key'))
      const owner = hex(inp, 'ownerId')
      const type = str(inp, 'type') as RefUpdateType
      const name = str(inp, 'refName')
      const newOid = hex(inp, 'newOid')
      const prevOid = optHex(inp, 'prevOid')
      const salt = hex(inp, 'salt')
      const force = inp['force'] === true
      let sealed
      try {
        sealed = await sealMembersRefWithNonce(keys, owner, { type, name, newOid, prevOid, force }, salt, hex(inp, 'nonce'))
      } catch (e) {
        return sealError(e)
      }
      // the TLV and the AD, recomputed from their definitions rather than read back from the seal
      const header: PrivateDoc = {
        type,
        vis: 'public',
        ownerId: owner,
        epoch,
        refNameHash: sealed.refNameHash,
        newOid: sealed.newOid,
        prevOid: sealed.prevOid,
        force: sealed.force,
      }
      const real = (o: Uint8Array | undefined) => (o === undefined || isNull(o) ? undefined : o)
      const fields: DocFields = { refName: name, newOid: real(newOid), prevOid: real(prevOid), oidSalt: salt }
      const doc: { [k: string]: Json } = {
        epoch: sealed.epoch,
        refNameHash: bytesToHex(sealed.refNameHash),
        newOid: bytesToHex(sealed.newOid),
        force: sealed.force,
      }
      if (sealed.prevOid !== undefined) doc['prevOid'] = bytesToHex(sealed.prevOid)
      expect(bytesToHex(sealed.salt)).toBe(bytesToHex(salt))
      return {
        doc,
        tlv: bytesToHex(encodeTlv(Object.fromEntries(Object.entries(fields).filter(([, v]) => v !== undefined)) as DocFields)),
        ad: bytesToHex(docAd(header, keys, V3)),
        enc: bytesToHex(sealed.enc),
      }
    }
    case 'open': {
      const ctx = await openContextOf(repoId, obj(inp, 'context'))
      const doc = storedDoc(obj(inp, 'doc'))
      // a private repository's (v0x01) update: its plaintext OIDs are real
      return doc.enc[0] === V3 ? refOpenedJson(await openMembersRef(doc, ctx)) : openJson(await openContent(doc, ctx))
    }
    case 'union': {
      const ctx = await openContextOf(repoId, obj(inp, 'context'))
      const refUpdate: PlainDocument[] = []
      const protectedRefUpdate: PlainDocument[] = []
      for (const row of arr(inp, 'rows')) {
        const { doc, isProtected } = rowDoc(row)
        ;(isProtected ? protectedRefUpdate : refUpdate).push(doc)
      }
      const got = await membersUpdatesOf({ refUpdate, protectedRefUpdate }, (d) => openContent(d, ctx))
      // the public reader: the plaintext updates alone, grouped by their own refNameHash
      const publicByHash = new Map<string, RefUpdate[]>()
      for (const [rows, isProtected] of [[refUpdate, false], [protectedRefUpdate, true]] as const) {
        for (const d of rows) {
          if (!gitPlaneDocWellFormed('refUpdate', d)) continue
          const u = toRefUpdate(d, isProtected)
          if (u.refNameHash.length !== 64) continue
          publicByHash.set(u.refNameHash, [...(publicByHash.get(u.refNameHash) ?? []), u])
        }
      }
      const publicRefs: { [k: string]: Json } = {}
      for (const us of publicByHash.values()) {
        const sorted = [...us].sort(compareKey)
        publicRefs[(sorted[0] as RefUpdate).refName] = sorted.map(updateJson)
      }
      return {
        refs: Object.fromEntries([...got.byName].map(([n, us]) => [n, us.map(updateJson)])),
        publicRefs,
        alerts: got.alerts.map((a) => ({ ...a, id: bytesToHex(base58Decode(a.id)) })),
        unreadable: got.unreadable,
      }
    }
    default:
      throw new Error(`sealed_ref op ${str(inp, 'op')}`)
  }
}

// ---------------------------------------------------------------------------------------------
// sealed_patch
// ---------------------------------------------------------------------------------------------

/** Props the writers hand over as bytes (ids and byte arrays), hex in the vectors (forge-core `COLLAB_BYTES`). */
const BYTE_PROPS = new Set(['targetId', 'patchId', 'sourceRepoId', 'replyTo', 'reviewId', 'headOid', 'commitOid', 'patchManifestHash', 'baseRefNameHash', 'sourceRefNameHash', 'refId', 'oid', 'enc'])

async function runSealedPatch(inp: Obj): Promise<Json> {
  const repoId = hex(inp, 'repoId')
  switch (str(inp, 'op')) {
    case 'seal': {
      const keys = await EpochKeys.import(repoId, num(inp, 'epoch'), hex(inp, 'key'))
      const nonce = hex(inp, 'nonce')
      const props: Record<string, unknown> = {}
      for (const [k, v] of Object.entries(obj(inp, 'props'))) props[k] = BYTE_PROPS.has(k) && typeof v === 'string' ? hexToBytes(v) : v
      const head = isObj(inp['head']) ? { real: hex(inp['head'], 'real'), salt: hex(inp['head'], 'salt') } : undefined
      let sealed: Record<string, unknown>
      try {
        sealed = await sealContent(
          keys,
          str(inp, 'type') as PrivateDocType,
          hex(inp, 'ownerId'),
          props,
          async (k, doc, f) => (await sealMembersDocWithNonce(k, { ...doc, vis: 'public' }, f, nonce)).enc,
          { basePublic: inp['basePublic'] === true, sourcePublic: inp['sourcePublic'] === true, head },
        )
      } catch (e) {
        return sealError(e)
      }
      const out: { [k: string]: Json } = {}
      for (const [k, v] of Object.entries(sealed)) out[k] = v instanceof Uint8Array ? bytesToHex(v) : (v as Json)
      return { props: out }
    }
    case 'open': {
      const ctx = await openContextOf(repoId, obj(inp, 'context'))
      const opened = await openContent(storedDoc(obj(inp, 'doc')), ctx)
      if (opened.status !== 'readable') return openJson(opened)
      const { headOid, oidSalt, ...rest } = opened.fields
      const head = await headOf(hex(inp, 'plainHead'), headOid, oidSalt)
      if (head === null) return { status: 'malformed' }
      const out: { [k: string]: Json } = { status: 'readable', fields: fieldsJson(rest), alerts: [] }
      if (head.kind === 'real') out['head'] = { real: bytesToHex(head.real), salt: bytesToHex(head.salt) }
      if (head.kind === 'alert') out['alerts'] = [alertJson(head.alert)]
      return out
    }
    default:
      throw new Error(`sealed_patch op ${str(inp, 'op')}`)
  }
}

function run(v: Vector): Promise<Json> {
  switch (v.case) {
    case 'oid_blind':
      return runOidBlind(v.input)
    case 'sealed_ref':
      return runSealedRef(v.input)
    case 'sealed_patch':
      return runSealedPatch(v.input)
    default:
      throw new Error(`not a members-git case: ${v.case}`)
  }
}

describe('members-only branch and pull request conformance vectors', () => {
  const vectors: Vector[] = FILES.map((f) => JSON.parse(readFileSync(resolve(VECTORS_DIR, f), 'utf8')) as Vector)
  const ran = new Map<string, number>()

  for (const v of vectors) {
    it(`${v.case} :: ${v.name}`, async () => {
      expect(CASES).toContain(v.case)
      expect(v.rules).toBe('v2')
      checkShape(v.input, SHAPES[v.case] as Shape, `${v.name}.input`)
      expect(await run(v)).toEqual(v.expected)
      ran.set(v.case, (ran.get(v.case) ?? 0) + 1)
    })
  }

  it('ran every oid_blind, sealed_ref and sealed_patch vector', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(69)
    for (const c of CASES) expect(ran.get(c) ?? 0, c).toBeGreaterThanOrEqual(5)
    expect([...ran.values()].reduce((a, b) => a + b, 0)).toBe(FILES.length)
  })
})
